import {useState, useEffect} from "react";
import EntityCard from "./components/EntityCard";
import AddEntityForm from "./components/AddEntityForm";
import EditEntityForm from "./components/EditEntityForm";
import {getEntities, createEntity, updateEntity, deleteEntity, generateEntity} from "./api/entities";

function App() {
    const [entities, setEntities] = useState([]);
    const [editingEntity, setEditingEntity] = useState(null);
    const [preview, setPreview] = useState(null);
    const [pendingTitle, setPendingTitle] = useState("");

    useEffect(() => {
        getEntities().then(data => setEntities(data));
    }, []);

    const handleAdd = (prompt, entityType) => {
        generateEntity(entityType, prompt)
            .then(result => {
                // store the preview and the original prompt as the title
                setPreview({title: prompt, description: result.description});
                setPendingTitle(prompt);
            });
    };

    const handleConfirm = () => {
        createEntity({title: pendingTitle, body: preview.description})
            .then(newEntity => {
                setEntities(prev => [...prev, newEntity]);
                setPreview(null);
                setPendingTitle("");
            });
    };

    const handleDiscard = () => {
        setPreview(null);
        setPendingTitle("");
    };

    return (
        <div className="container mt-4">
            <h1 className="mb-4">Entities</h1>

            <AddEntityForm onAdd={handleAdd}/>

            {editingEntity && (
                <EditEntityForm
                    entity={editingEntity}
                    onSave={handleSave}
                    onCancel={() => setEditingEntity(null)}
                />
            )}

            <div className="row">
                {entities.map(entity => (
                    <div className="col-md-4" key={entity.id}>
                        <EntityCard
                            entity={entity}
                            onEdit={setEditingEntity}
                            onDelete={handleDelete}
                        />
                    </div>
                ))}
            </div>
        </div>
    );
}

export default App;
